-- Name: enqueue_marketplace_outbox_event(); Type: FUNCTION; Schema: public; Owner: app
--

CREATE FUNCTION public.enqueue_marketplace_outbox_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE event_payload JSONB;

event_aggregate_id TEXT;

event_type_value TEXT;

event_routing_key TEXT;

BEGIN IF TG_OP = 'DELETE' THEN event_payload := to_jsonb(OLD);

ELSE event_payload := to_jsonb(NEW);

END IF;

event_aggregate_id := COALESCE(event_payload->>'id', 'unknown');

event_type_value := format('%s.%s', lower(TG_TABLE_NAME), lower(TG_OP));

IF TG_TABLE_NAME = 'content_items' THEN event_routing_key := 'search.content.sync';

ELSIF TG_TABLE_NAME = 'transactions'

OR TG_TABLE_NAME = 'reviews' THEN event_routing_key := 'search.transaction.sync';

ELSE event_routing_key := 'search.generic.sync';

END IF;

INSERT INTO events.event_outbox (

    aggregate_type,

    aggregate_id,

    event_type,

    payload,

    routing_key

  )

VALUES (

    lower(TG_TABLE_NAME),

    event_aggregate_id,

    event_type_value,

    event_payload,

    event_routing_key

  );

IF TG_OP = 'DELETE' THEN RETURN OLD;

END IF;

RETURN NEW;

END;

$$;


