--
-- Name: update_content_rating(); Type: FUNCTION; Schema: public; Owner: app
--

CREATE FUNCTION public.update_content_rating() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

  UPDATE content_items

  SET 

    rating = (SELECT AVG(rating)::REAL FROM reviews WHERE content_id = NEW.content_id),

    review_count = (SELECT COUNT(*)::INT FROM reviews WHERE content_id = NEW.content_id),

    updated_at = NOW()

  WHERE id = NEW.content_id;

  RETURN NEW;

END;

$$;


ALTER FUNCTION public.update_content_rating() OWNER TO app;

